#!/usr/bin/env bash
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
: "${MATHLIB_DIR:?Path to built Mathlib at the pinned revision}"
lib=$(cd "$MATHLIB_DIR" && pwd)
lean=${LEAN_BIN:-lean}
[[ $(git -C "$lib" rev-parse HEAD) == d13f23b723b8a846827a245b89c10fc7d3f11612 ]]
"$lean" --version | grep -F 'version 4.34.1'
(cd "$here" && sha256sum -c SHA256SUMS)
out=$(mktemp -d)
trap 'rm -rf "$out"' EXIT
export LEAN_PATH="$out:$lib/.lake/build/lib/lean:$(find "$lib/.lake/packages" -type d -path '*/.lake/build/lib/lean' | paste -sd ':' -)"
for n in RobustFolkman MixedCorners ParagliderCayley GeometricGraphEdit GeometricMoment GeometricAssembly GeometricWindow GeometricPatterns GramLowOrder GramCoefficients GeometricGap GeometricHGram GeometricVariance GeometricTriangleOverlap GeometricConditioning GeometricChargeMoment GeometricChargeGraph GeometricChargeCount GeometricTriangleCount GeometricPatternAssembly GeometricAttachment GeometricSchurLocal GeometricNearIdentity GeometricLocalize GeometricAnchorBox GeometricDetLower GeometricProbe GeometricSaturated GeometricCompact GeometricExactScalar GeometricPage GeometricPageTransfer GeometricDiamond GeometricForbidden GeometricPatternDet GeometricRateWindow GeometricGraphMeasure GeometricUniformSphere GeometricPatternMeasure GeometricMarginals GeometricRotations GeometricSphereTransitive GeometricRootTriangle GeometricSharedRoot GeometricLaplaceBounds GeometricStrictGram GeometricChart GeometricChartVolume GeometricNormalization GeometricLogBounds GeometricNormalizedRate GeometricProjectionJacDet GeometricProjectionDerivative GeometricProjectionInverse GeometricProjectionChange GeometricConeRatio GeometricRadialIntegration GeometricResidualSplit GeometricProjectionFubini GeometricProjectionProduct GeometricAngularIntegration GeometricSphericalProjection GeometricProjectionLaw GeometricLinearProjection GeometricAnchorCoordinates GeometricAnchorDensity GeometricGramTelescope GeometricSphereTransport GeometricSpanProjection GeometricSpanAnchors GeometricGramConditional GeometricFixedAnchors GeometricSphereNull GeometricIIDAnchor GeometricGramBorder GeometricGramChartStep GeometricChartBorder GeometricSampleChart GeometricChartWeight GeometricChartConditional GeometricProjectionMass GeometricGramFiber GeometricJointGram GeometricJointGramNormalized GeometricSpherePatternRate GeometricActualRate GeometricDimensionScaling GeometricPowerRates GeometricFailurePowers GeometricPatternReindex GeometricMomentBounds GeometricCommonRates GeometricQuantitativeAssembly GeometricLabelShapes GeometricMomentEvents GeometricForbiddenLabels GeometricChargeEvents GeometricTriangleLabels GeometricDiamondEvents GeometricTrianglePacking GeometricRootOverlap GeometricDisjointOverlap GeometricTriangleCorr GeometricFolkmanConditional GeometricFolkmanReduction GeometricLinkCorners GeometricLinkMargin GeometricActualLinks GeometricLinkCuts GeometricQuadraticCuts GeometricNormalizedCut GeometricDirectedLinkSum GeometricSpectralInterface GeometricProductConditioning GeometricRootCap GeometricCapMass GeometricCapSelection GeometricCapCount GeometricWeightedLinks GeometricWeightedMoment GeometricWeightedFailure GeometricRootedCount GeometricRootedVariance GeometricRootedSecond GeometricRootedRates GeometricRootedPower GeometricRelativeLinks GeometricTypicalLink GeometricTypicalFolkman; do
  cap=2850; case "$n" in Geometric*Measure|GeometricUniformSphere|GeometricMarginals|GeometricRotations|GeometricSphereTransitive|GeometricRootTriangle|GeometricSharedRoot|GeometricLaplaceBounds|GeometricStrictGram|GeometricChart|GeometricChartVolume|GeometricNormalization|GeometricLogBounds|GeometricNormalizedRate|GeometricProjectionJacDet|GeometricProjectionDerivative|GeometricProjectionInverse|GeometricProjectionChange|GeometricConeRatio|GeometricRadialIntegration|GeometricResidualSplit|GeometricProjectionFubini|GeometricProjectionProduct|GeometricAngularIntegration|GeometricSphericalProjection|GeometricProjectionLaw|GeometricLinearProjection|GeometricAnchorCoordinates|GeometricAnchorDensity|GeometricGramTelescope|GeometricSphereTransport|GeometricSpanProjection|GeometricSpanAnchors|GeometricGramConditional|GeometricFixedAnchors|GeometricSphereNull|GeometricIIDAnchor|GeometricGramBorder|GeometricGramChartStep|GeometricChartBorder|GeometricSampleChart|GeometricChartWeight|GeometricChartConditional|GeometricProjectionMass|GeometricGramFiber|GeometricJointGram|GeometricJointGramNormalized|GeometricSpherePatternRate|GeometricActualRate|GeometricDimensionScaling|GeometricPowerRates|GeometricFailurePowers|GeometricPatternReindex|GeometricMomentBounds|GeometricCommonRates|GeometricQuantitativeAssembly|GeometricLabelShapes|GeometricMomentEvents|GeometricForbiddenLabels|GeometricChargeEvents|GeometricTriangleLabels|GeometricDiamondEvents|GeometricTrianglePacking|GeometricRootOverlap|GeometricDisjointOverlap|GeometricTriangleCorr|GeometricFolkmanConditional|GeometricFolkmanReduction|GeometricLinkCorners|GeometricLinkMargin|GeometricActualLinks|GeometricLinkCuts|GeometricQuadraticCuts|GeometricNormalizedCut|GeometricDirectedLinkSum|GeometricSpectralInterface|GeometricProductConditioning|GeometricRootCap|GeometricCapMass|GeometricCapSelection|GeometricCapCount|GeometricWeightedLinks|GeometricWeightedMoment|GeometricWeightedFailure|GeometricRootedCount|GeometricRootedVariance|GeometricRootedSecond|GeometricRootedRates|GeometricRootedPower|GeometricRelativeLinks|GeometricTypicalLink|GeometricTypicalFolkman) cap=4100;; esac
  "$lean" -j1 -M"$cap" --root="$here" -o "$out/$n.olean" "$here/$n.lean"
done
